// Copies the static assets the browser-side audit pipeline fetches at runtime from their
// real source of truth into frontend/public/, where Vite serves anything unmodified at
// the site root:
//   - ../../corpus/xsd/            -> public/xsd/             (git-tracked at source)
//   - ../../engine/catalog-bundle/ -> public/catalog-bundle/  (gitignored, generated by
//                                      engine's own postinstall -- see build-catalog-
//                                      bundle.mjs; run `npm install` in engine/ first if
//                                      this script warns it's missing)
//   - ../../corpus/efos/*.csv      -> public/efos/            (git-tracked at source; see
//                                      corpus/README.md for the freshness caveat this
//                                      file carries -- copying it doesn't change that)
// Both public/ copies are themselves gitignored (see .gitignore) and regenerated by this
// script via predev/prebuild -- same "cheap to regenerate, dangerous to let drift if
// committed" reasoning already applied to engine/catalog-bundle/ itself. Don't hand-edit
// anything under frontend/public/xsd/ or frontend/public/catalog-bundle/; edit the source
// trees instead and rerun this script (or just `npm run dev`/`npm run build`, which do).
import { cpSync, existsSync, mkdirSync, rmSync } from "node:fs";
import path from "node:path";

const ROOT = path.resolve(import.meta.dirname, "..");

const COPIES = [
  { src: path.resolve(ROOT, "../corpus/xsd"), dest: path.join(ROOT, "public/xsd") },
  { src: path.resolve(ROOT, "../engine/catalog-bundle"), dest: path.join(ROOT, "public/catalog-bundle") },
  {
    src: path.resolve(ROOT, "../corpus/efos/listado_completo_69b.csv"),
    dest: path.join(ROOT, "public/efos/listado_completo_69b.csv"),
  },
];

mkdirSync(path.join(ROOT, "public"), { recursive: true });

for (const { src, dest } of COPIES) {
  if (!existsSync(src)) {
    console.warn(
      `[sync-static-assets] ${src} not found -- skipping. The audit pipeline will fail to ` +
        "initialize at runtime until this exists (see this script's header comment for how to generate it).",
    );
    continue;
  }
  rmSync(dest, { recursive: true, force: true });
  mkdirSync(path.dirname(dest), { recursive: true });
  cpSync(src, dest, { recursive: true });
  console.log(`[sync-static-assets] ${src} -> ${dest}`);
}
